/**
 *
 * DrawerPopup is a component that displays the popup content of a drawer.
 *
 * [Live Demo](https://www.primereact.org/drawer/)
 *
 * @module DrawerPopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DrawerRootInstance } from './DrawerRoot.types';
/**
 * Defines passthrough(pt) options type in DrawerPopup component.
 */
export type DrawerPopupPassThroughType<E> = PassThroughType<DrawerPopupInstance, E>;
/**
 * Defines passthrough(pt) options of DrawerPopup component.
 */
export interface DrawerPopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DrawerPopupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DrawerPopup component.
 */
export interface DrawerPopupProps extends BaseComponentProps<DrawerPopupInstance, unknown, DrawerPopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in DrawerPopup component.
 */
export interface DrawerPopupState {
}
/**
 * Defines the methods and properties exposed by DrawerPopup component.
 */
export interface DrawerPopupExposes {
    /**
     * Instance of the Drawer component.
     */
    drawer: DrawerRootInstance | undefined | null;
}
/**
 * Instance of DrawerPopup component.
 */
export type DrawerPopupInstance = ComponentInstance<DrawerPopupProps, DrawerPopupState, DrawerPopupExposes>;
